// Questões próprias: os índices são estáveis para preservar tentativas e revisões.
const bank = []
function add(topicId, subject, text, correct, distractors, explanation) {
  const number = bank.filter(q => q.topicId === topicId).length + 1
  const options = [...distractors]
  const position = (number - 1) % 4
  options.splice(position, 0, correct)
  bank.push({ authoredId: `${topicId}-${String(number).padStart(2, '0')}`, topicId, number, subject, text, options, answer: 'ABCD'[position], explanation })
}
const n = value => Number(value.toFixed(4)).toLocaleString('pt-BR', { maximumFractionDigits: 4 })
function numeric(topic, text, value, wrong, unit, explanation) {
  add(topic, 'Matemática', text, `${n(value)}${unit}`, wrong.map(v => `${n(v)}${unit}`), explanation)
}
