  numeric(t, `Após um aumento de 20%, uma mensalidade passou a R$ ${120*k}. Quanto custava antes?`,100*k,[96*k,144*k,80*k],' reais', `O preço final corresponde a 1,20 vezes o inicial: ${120*k}/1,20 = ${100*k}.`)
