  numeric(t, `Um salário de R$ ${1000*k} aumenta 5%. Qual é o valor do aumento?`,50*k,[1050*k,5*k,100*k],' reais', `A questão pede somente o aumento: ${1000*k} × 0,05 = ${50*k}, e não o salário final.`)
  t = 'regra-de-tres'
  numeric(t, `${3*k} cadernos custam R$ ${24*k}. Mantendo o preço unitário, quanto custam ${5*k} cadernos?`,40*k,[32*k,15*k,120*k],' reais', `Cada caderno custa R$ 8. Logo ${5*k} × 8 = ${40*k}.`)
  numeric(t, `${4*k} trabalhadores fazem um serviço em 12 dias. Com ${6*k} trabalhadores de mesma produtividade, quantos dias são necessários?`,8,[18,6,10],' dias', 'A relação é inversa: trabalhadores × dias é constante. Portanto 4 × 12/6 = 8 dias.')
  numeric(t, `Uma viagem de ${180*k} km é feita a 60 km/h constantes. Quanto tempo ela dura?`,3*k,[2*k,4*k,6*k],' horas', `Tempo = distância/velocidade = ${180*k}/60 = ${3*k}.`)
  numeric(t, `Em um mapa de escala 1:100.000, duas cidades distam ${3*k} cm. Qual é a distância real em quilômetros?`,3*k,[30*k,.3*k,300*k],' km', 'Cada centímetro representa 100.000 cm = 1 km. Multiplique a medida do mapa por 1 km.')
  numeric(t, `Uma receita para 4 pessoas usa ${200*k} g de arroz. Quanto usar para 10 pessoas?`,500*k,[80*k,400*k,1000*k],' g', `A quantidade é diretamente proporcional: ${200*k} × 10/4 = ${500*k} g.`)
  numeric(t, `${2*k} máquinas produzem 80 peças em 4 horas. Quantas peças ${3*k} máquinas iguais produzem em 6 horas?`,180,[120,160,240],' peças', 'A produção varia com máquinas e horas: 80 × (3/2) × (6/4) = 180 peças.')
  numeric(t, `Uma torneira despeja ${6*k} litros por minuto. Quantos litros despeja em 15 minutos?`,90*k,[21*k,60*k,120*k],' litros', `Volume = vazão × tempo = ${6*k} × 15 = ${90*k} litros.`)
  numeric(t, `Um carro consome 1 litro a cada 12 km. Quantos litros usa para percorrer ${240*k} km?`,20*k,[12*k,24*k,2880*k],' litros', `Consumo = ${240*k}/12 = ${20*k} litros, mantendo as condições de rendimento.`)
  numeric(t, `Uma peça de ${60*k} cm é desenhada na escala 1:5. Qual é o comprimento no desenho?`,12*k,[300*k,5*k,30*k],' cm', `Medida desenhada = medida real/5 = ${60*k}/5 = ${12*k} cm.`)
  numeric(t, `A ${40*k} km/h, uma entrega leva 3 horas. A ${60*k} km/h no mesmo percurso, quanto tempo levará?`,2,[4.5,1.5,3],' horas', 'Para distância fixa, velocidade e tempo são inversos: 40 × 3/60 = 2 horas.')
  t = 'funcoes'
  numeric(t, `Uma corrida custa R$ ${5*k} fixos mais R$ 2 por km. Qual é o custo de ${10*k} km?`,25*k,[20*k,15*k,50*k],' reais', `C(x) = ${5*k} + 2x. Substituindo x = ${10*k}, temos ${25*k}.`)
