  numeric(t, `Qual é a raiz de f(x) = 3x − ${6*k}?`,2*k,[3*k,-2*k,6*k],'', `Na raiz, f(x)=0: 3x = ${6*k}, portanto x = ${2*k}.`)
  numeric(t, `Um reservatório tem ${100*k} litros e perde 5 litros por minuto. Após 8 minutos, qual é seu volume?`,100*k-40,[100*k+40,100*k-8,5*k],' litros', `V(t)=${100*k}−5t. Logo V(8)=${100*k}−40=${100*k-40}.`)
