  numeric(t, `Qual é o maior valor de f(x) = −x² + ${4*k}x?`,4*k*k,[2*k,8*k*k,-4*k*k],'', `A parábola tem concavidade para baixo. O vértice está em x=${2*k}; f(${2*k})=${4*k*k}.`)
  numeric(t, `Qual é o menor valor de f(x) = (x − ${3*k})² + 2?`,2,[0,3*k,-2],'', `Um quadrado é não negativo. Seu mínimo é zero quando x=${3*k}, então o valor mínimo da função é 2.`)
  numeric(t, `Na função f(x) = ${5*k} − 2x, qual é a ordenada na origem?`,5*k,[-2,-5*k,2.5*k],'', `A ordenada na origem é f(0) = ${5*k}; não é a raiz nem o coeficiente de x.`)
  numeric(t, `Uma população segue P(t) = ${100*k} × 2ᵗ. Qual é P(3)?`,800*k,[300*k,600*k,200*k],' indivíduos', `2³=8. Portanto P(3)=${100*k} × 8=${800*k}.`)
  numeric(t, `Uma loja tem receita R(x)=20x e custo C(x)=${100*k}+10x. Quantas unidades precisa vender para receita e custo serem iguais?`,10*k,[5*k,20*k,100*k],' unidades', `Iguale as funções: 20x=${100*k}+10x. Assim 10x=${100*k} e x=${10*k}.`)
  t = 'geometria'
  numeric(t, `Um terreno retangular mede ${8*k} m por 5 m. Qual é sua área?`,40*k,[26*k,13*k,80*k],' m²', `Área do retângulo = base × altura = ${8*k} × 5 = ${40*k} m².`)
  numeric(t, `Um triângulo tem base ${12*k} cm e altura perpendicular de 5 cm. Qual é sua área?`,30*k,[60*k,17*k,120*k],' cm²', `Área = base × altura/2 = ${12*k} × 5/2 = ${30*k} cm².`)
  numeric(t, `Um quadrado tem lado ${6*k} m. Qual é seu perímetro?`,24*k,[36*k*k,12*k,6*k],' m', `Perímetro soma os quatro lados: 4 × ${6*k} = ${24*k} m.`)
  numeric(t, `Um círculo tem raio ${3*k} cm. Usando π=3, qual é sua área?`,27*k*k,[18*k,12*k*k,54*k*k],' cm²', `Área=πr²=3 × (${3*k})²=${27*k*k} cm².`)
  numeric(t, `Uma caixa mede ${2*k} m por 3 m por 4 m. Qual é seu volume?`,24*k,[9*k,12*k,48*k],' m³', `Volume do paralelepípedo = ${2*k} × 3 × 4 = ${24*k} m³.`)
  numeric(t, `Um cubo de aresta ${2*k} cm tem qual área total?`,24*k*k,[8*k*k*k,4*k*k,12*k*k],' cm²', `São seis faces quadradas: 6 × (${2*k})² = ${24*k*k} cm².`)
  numeric(t, `Uma escada forma um triângulo retângulo com catetos ${3*k} m e ${4*k} m. Qual é a hipotenusa?`,5*k,[7*k,25*k*k,6*k],' m', `Pelo teorema de Pitágoras: h²=(${3*k})²+(${4*k})²=${25*k*k}. Logo h=${5*k} m.`)
  numeric(t, `Um cilindro tem raio ${2*k} cm e altura 5 cm. Adotando π=3, qual é seu volume?`,60*k*k,[30*k*k,20*k,120*k*k],' cm³', `Volume=πr²h=3 × (${2*k})² × 5 = ${60*k*k} cm³.`)
  numeric(t, `Uma planta tem ${2*k} m² de área real. Quantos centímetros quadrados equivalem a essa área?`,20000*k,[200*k,2000*k,20*k],' cm²', `1 m² = (100 cm)² = 10.000 cm². Logo ${2*k} m² = ${20000*k} cm².`)
  numeric(t, `Dois quadrados semelhantes têm lados ${2*k} cm e ${6*k} cm. Quantas vezes a área do maior é a do menor?`,9,[3,6,27],' vezes', 'A razão dos lados é 3; a razão das áreas é o quadrado dessa razão: 3²=9.')
