  numeric(t, `Ordenando os valores ${8*k}, ${2*k}, ${5*k}, ${1*k} e ${9*k}, qual é a mediana?`,5*k,[2*k,8*k,9*k],'', `A lista ordenada é ${k}, ${2*k}, ${5*k}, ${8*k}, ${9*k}. O terceiro termo é ${5*k}.`)
  numeric(t, `Qual é a mediana dos valores ${2*k}, ${4*k}, ${8*k} e ${10*k}?`,6*k,[4*k,8*k,24*k],'', `Com quatro valores ordenados, calcule a média dos dois centrais: (${4*k}+${8*k})/2=${6*k}.`)
  numeric(t, `Na lista ${k}, ${3*k}, ${3*k}, ${5*k}, ${7*k}, qual é a moda?`,3*k,[k,5*k,7*k],'', `A moda é o valor mais frequente. ${3*k} aparece duas vezes; os demais aparecem uma vez.`)
  numeric(t, `As temperaturas variaram entre ${12*k} e ${20*k} graus. Qual é a amplitude?`,8*k,[32*k,16*k,20*k],' graus', `Amplitude = máximo − mínimo = ${20*k}−${12*k}=${8*k}.`)
  numeric(t, `Uma avaliação de nota ${6*k} tem peso 1 e outra de nota ${9*k} tem peso 2. Qual é a média ponderada?`,8*k,[7.5*k,15*k,24*k],'', `A média ponderada é (${6*k}×1+${9*k}×2)/(1+2)=${8*k}.`)
  numeric(t, `Uma pesquisa registra ${20*k} votos para A, ${30*k} para B e ${50*k} para C. Qual é a frequência relativa de B?`,30,[20,50,60],'%', `B tem ${30*k} de ${100*k} votos: 30/100 = 30%.`)
  numeric(t, `Vendas foram ${10*k} na segunda, ${15*k} na terça e ${25*k} na quarta. Qual é o total?`,50*k,[25*k,40*k,15*k],' vendas', `Some as três frequências: ${10*k}+${15*k}+${25*k}=${50*k}.`)
  numeric(t, `A média de quatro valores é ${5*k}. Ao acrescentar ${10*k}, qual é a nova média?`,6*k,[7.5*k,5*k,10*k],'', `A soma anterior era 4 × ${5*k}=${20*k}. A nova média é (${20*k}+${10*k})/5=${6*k}.`)
  numeric(t, `Qual é a média de ${2*k}, ${2*k}, ${2*k} e ${10*k}?`,4*k,[2*k,10*k,16*k],'', `A soma é ${16*k} e há quatro valores. A média é ${4*k}; o valor alto a desloca acima da mediana.`)
