  numeric(t, `Uma caixa tem ${k} bola verde e ${4*k} amarelas. Qual é a chance de retirar uma bola que não seja verde?`,80,[20,25,75],'%', 'O evento complementar tem probabilidade 1−1/5=4/5=80%.')
  numeric(t, `Uma urna tem ${2*k} bolas pretas e ${2*k} brancas. Com reposição, qual é a chance de retirar duas pretas?`,25,[50,75,100],'%', 'Com reposição, os sorteios são independentes. A chance é 1/2 × 1/2 = 1/4 = 25%.')
  numeric(t, `Uma urna tem ${3*k} bolas azuis e ${2*k} vermelhas. Sem reposição, quantos objetos restam após a primeira retirada?`,5*k-1,[5*k,3*k,2*k],' bolas', `Sem reposição, o total diminui uma unidade: ${5*k}−1=${5*k-1}. Esse é o denominador do segundo sorteio.`)
